"""Consolidação, verificação e relatório interativo offline."""
from __future__ import annotations
import json,html,hashlib,os,datetime
from pathlib import Path
import numpy as np,pandas as pd
from collections import Counter
from analise_estadual import load,TIPOS,OUT

ROOT=Path(__file__).resolve().parents[1]
DOC=ROOT/'docs'; DOC.mkdir(exist_ok=True)
REPORT=ROOT/'outputs/reports'; REPORT.mkdir(exist_ok=True,parents=True)

def tab(n):return pd.read_csv(OUT/(n+'.csv'),encoding='utf-8-sig')
def tojson(d):return json.dumps(d.replace({np.nan:None}).to_dict('records'),ensure_ascii=False,separators=(',',':'),default=str)

def consolidate():
 d=load();g=tab('granger_aplicacoes');k=tab('dlm_selecao');h=tab('dlm_hipoteses');diag=tab('dlm_diagnosticos_fe_re')
 sarima=pd.concat([tab('sarima_referencia_Pré'),tab('sarima_referencia_Total')],ignore_index=True)
 sarimax=pd.concat([tab('sarimax_modelos_Pré'),tab('sarimax_modelos_Total')],ignore_index=True)
 coef=tab('sarimax_coeficientes_Total');adf=tab('estacionariedade_adf_kpss')
 assert len(g)==864 and g.groupby(['periodo','uf']).size().eq(16).all()
 assert len(k)==64 and len(k[k.status=='estimado'])==58
 assert k[k.status=='estimado'].query('criterio=="BIC"').K.eq(1).all()
 assert len(h)==1160 and (h.p.dropna().between(0,1)).all()
 assert len(diag)==29 and len(sarima)==54 and len(sarimax)==54 and len(coef)==80
 assert len(adf)==918
 assert len(sarimax[sarimax.rank_total==16])==5
 assert sarimax[(sarimax.rank_treino==16) & (sarimax.periodo=='Total')].uf.tolist()==['MG']
 assert int(d.total_desastres.sum())==40339
 assert d[TIPOS].sum().sum()==40339
 # Verificação exata do conteúdo original compatível com manifesto histórico.
 base=Path(os.getenv('TCC_BASE_CSV',str(ROOT/'data/processed/df_tcc_2013_2024.csv'))).read_bytes()
 # Normaliza apenas BOM e quebras de linha; suporta CSV original e CSV reconstruído em LF.
 base=base.removeprefix(b'\xef\xbb\xbf').replace(b'\r\n',b'\n')
 canonical=b'\xef\xbb\xbf'+base.replace(b'\n',b'\r\n')
 sha=hashlib.sha256(canonical).hexdigest();assert sha=='46f4f8408f5f6a809de2601b5c313ea52ee5992ed5a65ede5246c57d28767e36',sha
 # Verificação de q BH Granger em cada família fixa de 16 resultados:
 for _,z in g.groupby(['periodo','uf']):
  assert len(z)==16 and len(set(z.tipologia))==16
 # Notebooks precisam reproduzir o mesmo seletor que esta auditoria.
 master=[]
 for _,r in g.iterrows():master.append(dict(etapa='Granger',uf=r.uf,periodo=r.periodo,tipologia=r.tipologia,modelo='OLS autoregressivo + x defasado',criterio='BIC',K=r.p_lags,hipotese='lags de exposição = 0',estimativa=np.nan,erro_padrao=np.nan,p=r.p,q_bh=r.q_bh,rejeicao_nominal=r.rejeicao_nominal,rejeicao_bh=r.rejeicao_bh,status=r.status,diagnostico=r.get('diagnostico',np.nan),N=r.n_eff))
 for _,r in h.iterrows():master.append(dict(etapa='DLM',uf='Painel 27 UFs',periodo=r.periodo,tipologia=r.tipologia,modelo='TWFE',criterio=r.criterio,K=r.K,hipotese=r.endpoint+' / '+r.covariancia,estimativa=r.estimate,erro_padrao=r.se,p=r.p,q_bh=r.q_bh,p_grade=r.p_grade_bonferroni,q_bh_grade=r.q_bh_grade,rejeicao_nominal=r.rejeicao_nominal,rejeicao_bh=r.rejeicao_bh,rejeicao_bh_grade=r.rejeicao_bh_grade,status=r.status,diagnostico='covariância: '+r.covariancia,N=1620 if r.periodo=='Pré' else 3213))
 for _,r in sarimax.iterrows():master.append(dict(etapa='SARIMAX conjunto',uf=r.uf,periodo=r.periodo,tipologia='16 simultâneas',modelo='SARIMA com 16 exógenas',criterio='BIC do SARIMA',K=np.nan,hipotese='16 betas = 0',estimativa=r.get('LR',np.nan),erro_padrao=np.nan,p=r.get('p_conjunto',np.nan),q_bh=np.nan,rejeicao_nominal=(pd.notna(r.get('p_conjunto')) and r.get('p_conjunto')<.05),rejeicao_bh=np.nan,status=r.status,diagnostico=r.get('sarimax_ljungbox_p',np.nan),N=r.n))
 for _,r in coef.iterrows():master.append(dict(etapa='SARIMAX individual',uf=r.uf,periodo=r.periodo,tipologia=r.tipologia,modelo='SARIMA com 16 exógenas',criterio='BIC do SARIMA',K=0,hipotese='coeficiente contemporâneo=0',estimativa=r.coeficiente,erro_padrao=r.se,p=r.p,q_bh=r.q_bh,rejeicao_nominal=r.rejeicao_nominal,rejeicao_bh=r.rejeicao_bh,status='estimado; condicional a 15 exposições',N=143))
 m=pd.DataFrame(master);m.to_csv(OUT/'consolidado_mestre.csv',index=False,encoding='utf-8-sig')
 for label,query in [('dlm_aic',h.criterio=='AIC'),('dlm_bic',h.criterio=='BIC')]:
  z=h[query];z[z.rejeicao_nominal].to_csv(OUT/(label+'_rejeicoes_nominais.csv'),index=False,encoding='utf-8-sig')
  z[z.rejeicao_bh].to_csv(OUT/(label+'_rejeicoes_bh.csv'),index=False,encoding='utf-8-sig')
  z[z.rejeicao_bh_grade].to_csv(OUT/(label+'_rejeicoes_grade.csv'),index=False,encoding='utf-8-sig')
 sarimax[sarimax.p_conjunto<.05].to_csv(OUT/'sarimax_conjunto_rejeicoes.csv',index=False,encoding='utf-8-sig')
 coef[coef.rejeicao_nominal].to_csv(OUT/'sarimax_individuais_nominais.csv',index=False,encoding='utf-8-sig')
 coef[coef.rejeicao_bh].to_csv(OUT/'sarimax_individuais_bh.csv',index=False,encoding='utf-8-sig')
 # Pontos principais do sumário, sem misturar aplicabilidade e rejeição.
 summary={
  'data':'2026-10-19','hash_base_consolidada':sha,'tamanho_painel':len(d),'ufs':d.uf.nunique(),'meses':d.mes_ano.nunique(),'tipologias':len(TIPOS),'registros_atlas_reconciliados_historicamente':int(d.total_desastres.sum()),
  'granger_planejados':len(g),'granger_estimados':int((g.status=='estimado').sum()),'granger_nao_estimados':int((g.status!='estimado').sum()),'granger_nominais':int(g.rejeicao_nominal.sum()),'granger_bh':int(g.rejeicao_bh.sum()),'granger_bh_sem_rejeicao_LB':int((g.rejeicao_bh&(g.ljungbox_p>=.05)).sum()),
  'dlm_planejados':32,'dlm_estimaveis':int((k[(k.criterio=='BIC')].status=='estimado').sum()),'dlm_K_BIC_1':int((k.query('criterio=="BIC"').K==1).sum()),'dlm_divergencias_K':int(((k.query('criterio=="AIC"').set_index(['periodo','tipologia']).K!=k.query('criterio=="BIC"').set_index(['periodo','tipologia']).K)&k.query('criterio=="AIC"').set_index(['periodo','tipologia']).K.notna()).sum()),
  'dlm_BIC_DKregra_grade_bh':int(h.query('criterio=="BIC" and covariancia=="dk_regra"').rejeicao_bh_grade.sum()),
  'dlm_AIC_DKregra_grade_bh':int(h.query('criterio=="AIC" and covariancia=="dk_regra"').rejeicao_bh_grade.sum()),
  'dlm_FE_F_rejeicao':int((diag.p_F<.05).sum()),'dlm_RE_LM_rejeicao':int((diag.p_LM<.05).sum()),'dlm_Hausman_disponiveis':int(diag.p_Hausman.notna().sum()),'dlm_Hausman_rejeicao':int((diag.p_Hausman<.05).sum()),
  'sarima_ajustados':len(sarima),'sarima_LB_treino_ruim':int((sarima.ljungbox_p<.05).sum()),'sarimax_cenarios':len(sarimax),'sarimax_estimaveis_periodo_total':int(((sarimax.periodo=='Total')&(sarimax.rank_total==16)).sum()),'sarimax_estimaveis_pre':int(((sarimax.periodo=='Pré')&(sarimax.rank_total==16)).sum()),'sarimax_conjunto_rejeicoes':int((sarimax.p_conjunto<.05).sum()),'sarimax_individuais_nominais':int(coef.rejeicao_nominal.sum()),'sarimax_individuais_bh':int(coef.rejeicao_bh.sum()),'sarimax_BIC_melhor':int((sarimax.delta_BIC<0).sum()),'sarimax_RMSE_comparavel':int(sarimax.RMSE_SARIMAX.notna().sum()) if 'RMSE_SARIMAX' in sarimax else 0,
  'MG_delta_RMSE_pct':float(sarimax.loc[(sarimax.uf=='MG')&(sarimax.periodo=='Total'),'variacao_RMSE_pct'].iloc[0]),
  'limite_material_atlas':'Atlas bruto não materializável nesta sessão; classificação/códigos pré-auditados reaproveitados, sem reauditoria de registros'
 }
 (OUT/'resumo_validado.json').write_text(json.dumps(summary,ensure_ascii=False,indent=2),encoding='utf-8')
 return summary,{'granger':g,'dlm':h,'selecao':k,'diagnosticos':diag,'sarima':sarima,'sarimax':sarimax,'coef':coef,'adf':adf,'master':m}

